const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,SHA=process.env.TARGET_SHA,BLOB=process.env.TARGET_BLOB,assert=(x,m)=>{if(!x)throw new Error(m)},sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important,winnerSelector:l.selector,winnerContext:l.context});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
assert(sh('git rev-parse HEAD')===SHA,'wrong parent SHA');assert(sh(`git hash-object ${TARGET}`)===BLOB,'parent blob drift');const src=fs.readFileSync(TARGET,'utf8'),p=parse(src);assert(p.declarations.length===50&&p.dead.length===1,`parent drift ${p.declarations.length}/${p.dead.length}`);const d=p.dead[0];assert(d.line===23&&d.winnerLine===205,'cascade line drift');assert(d.property==='box-shadow'&&d.value==='var(--profile-surface-shadow)'&&d.winnerValue==='var(--doke-shadow-nested-soft)','cascade value drift');assert(d.selector===d.winnerSelector&&d.context===d.winnerContext&&d.important===d.winnerImportant,'dominance drift');const nl=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(nl&&lines.at(-1)==='')lines.pop();assert(lines[22]?.trim()==='box-shadow: var(--profile-surface-shadow);','source line mismatch');lines.splice(22,1);fs.writeFileSync(TARGET,lines.join('\n')+(nl?'\n':''));const after=parse(fs.readFileSync(TARGET,'utf8'));assert(after.declarations.length===49&&after.dead.length===0,`candidate drift ${after.declarations.length}/${after.dead.length}`);const stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(stat[0]==='0'&&stat[1]==='1'&&stat[2]===TARGET,`diff drift ${stat.join(' ')}`);const buf=fs.readFileSync(TARGET),hash=crypto.createHash('sha256').update(buf).digest('hex');assert(hash==='2fb0f03cc13a1f14688b7b03cbc2ae21ca223588e2f3586945ea9a2b1630eff4',`hash drift ${hash}`);assert(buf.length===5806,`bytes drift ${buf.length}`);console.log(`CANDIDATE BUILD PASS|decl=50->49|dead=1->0|families=1|identical=0|changed=1|unconditionalDominance=1|additions=0|deletions=1|hash=${hash}|bytes=${buf.length}`);
